-- Health cell (health), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA health;

CREATE FUNCTION health.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE health.health_metrics (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    source                   text NOT NULL CHECK (length(source) >= 1),
    metric_type              text NOT NULL CHECK (length(metric_type) >= 1),
    value                    double precision NOT NULL,
    unit                     text,
    recorded_at              timestamptz NOT NULL,
    metadata                 text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX health_metrics_legacy ON health.health_metrics (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE health.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('health-metric')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE health.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON health.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['health_metrics', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE health.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE health.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON health.%I'
                       ' USING (workspace_id = health.current_workspace())'
                       ' WITH CHECK (workspace_id = health.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA health TO health_api;
GRANT EXECUTE ON FUNCTION health.current_workspace() TO health_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON health.health_metrics TO health_api;
GRANT USAGE ON SEQUENCE health.health_metrics_id_seq TO health_api;
GRANT SELECT, INSERT ON health.create_keys TO health_api;
GRANT SELECT, INSERT ON health.outbox TO health_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON health.outbox TO health_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON health.outbox TO health_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA health TO health_publisher;
GRANT SELECT ON health.outbox TO health_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON health.outbox TO health_publisher;
